async fn copy_raw_directory(source: &Path, destination: &Path) -> Result<(), EntitySearchPipelineError> {
    let mut directories = vec![(source.to_path_buf(), destination.to_path_buf())];
    while let Some((source, destination)) = directories.pop() {
        if !fs::symlink_metadata(&source)
            .await
            .map_err(|error| read_error(&source, error))?
            .is_dir()
        {
            return Err(read_error(&source, "expected a raw directory, not a symlink or special file"));
        }
        fs::create_dir(&destination).await.map_err(|error| write_error(&destination, error))?;
        let mut entries = fs::read_dir(&source).await.map_err(|error| read_error(&source, error))?;
        while let Some(entry) = entries.next_entry().await.map_err(|error| read_error(&source, error))? {
            let source = entry.path();
            let destination = destination.join(entry.file_name());
            let kind = entry.file_type().await.map_err(|error| read_error(&source, error))?;
            if kind.is_dir() {
                directories.push((source, destination));
            } else if kind.is_file() {
                fs::copy(&source, &destination).await.map_err(|error| write_error(&destination, error))?;
            } else {
                return Err(read_error(&source, "raw data contains a symlink or special file"));
            }
        }
    }
    Ok(())
}

